## Concurrent Access Example

```go
package main

import (
    "fmt"
    "sync"
    "time"
    "your-module/cache"
)

func main() {
    // Thread-safe cache for concurrent access
    c := cache.New(10 * time.Minute)
    var wg sync.WaitGroup

    // Multiple goroutines writing to cache concurrently
    for i := 0; i < 10; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            // Thread-safe write operation
            c.Set(fmt.Sprintf("worker:%d", id), fmt.Sprintf("data-%d", id))
            fmt.Printf("Worker %d stored data\n", id)
        }(i)
    }

    // Multiple goroutines reading from cache concurrently
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            key := fmt.Sprintf("worker:%d", id)
            // Thread-safe read operation
            if value, found := c.Get(key); found {
                fmt.Printf("Reader found: %s = %s\n", key, value)
            }
        }(i)
    }

    wg.Wait()
    fmt.Println("All concurrent operations completed safely")
}
```

## Session Management Example

```go
package main

import (
    "fmt"
    "net/http"
    "time"
    "your-module/cache"
)

// Thread-safe session cache
var sessionCache = cache.New(30 * time.Minute)

type SessionData struct {
    UserID   string
    Username string
    LoginTime time.Time
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
    sessionID := generateSessionID() // Your session ID generation

    // Store session data - thread-safe operation
    sessionData := SessionData{
        UserID:    "user123",
        Username:  "alice",
        LoginTime: time.Now(),
    }
    sessionCache.Set(sessionID, sessionData)

    // Set session cookie
    http.SetCookie(w, &http.Cookie{
        Name:  "session_id",
        Value: sessionID,
    })

    fmt.Fprintf(w, "Login successful")
}

func authenticatedHandler(w http.ResponseWriter, r *http.Request) {
    cookie, err := r.Cookie("session_id")
    if err != nil {
        http.Error(w, "No session", http.StatusUnauthorized)
        return
    }

    // Thread-safe session lookup
    if sessionData, found := sessionCache.Get(cookie.Value); found {
        session := sessionData.(SessionData)
        fmt.Fprintf(w, "Welcome %s!", session.Username)
    } else {
        http.Error(w, "Session expired", http.StatusUnauthorized)
    }
}

func logoutHandler(w http.ResponseWriter, r *http.Request) {
    cookie, err := r.Cookie("session_id")
    if err != nil {
        return
    }

    // Thread-safe session removal
    sessionCache.Delete(cookie.Value)
    fmt.Fprintf(w, "Logged out successfully")
}

func generateSessionID() string {
    // Implementation for session ID generation
    return fmt.Sprintf("sess_%d", time.Now().UnixNano())
}
```

## Cache with Periodic Cleanup Example

```go
package main

import (
    "fmt"
    "time"
    "your-module/cache"
)

func main() {
    // Thread-safe cache for application data
    appCache := cache.New(2 * time.Minute)

    // Start background cleanup routine
    go func() {
        ticker := time.NewTicker(5 * time.Minute)
        defer ticker.Stop()

        for {
            select {
            case <-ticker.C:
                // Thread-safe cache purge
                appCache.Purge()
                fmt.Println("Cache purged at", time.Now().Format("15:04:05"))
            }
        }
    }()

    // Simulate application usage
    for i := 0; i < 20; i++ {
        key := fmt.Sprintf("item:%d", i)
        value := fmt.Sprintf("data-%d", i)

        // Thread-safe cache operations
        appCache.Set(key, value)
        fmt.Printf("Stored: %s\n", key)

        // Check if item exists
        if data, found := appCache.Get(key); found {
            fmt.Printf("Retrieved: %s = %s\n", key, data)
        }

        time.Sleep(30 * time.Second) // Wait to see TTL expiration
    }
}
```

