```go
package main

import (
    "encoding/json"
    "fmt"
    "net/http"
    "time"
    "your-module/cache"
)

// Thread-safe response cache
var responseCache = cache.New(15 * time.Minute)

type APIResponse struct {
    Data      interface{} `json:"data"`
    Timestamp time.Time   `json:"timestamp"`
    Cached    bool        `json:"cached"`
}

func expensiveAPIHandler(w http.ResponseWriter, r *http.Request) {
    cacheKey := fmt.Sprintf("api_response_%s", r.URL.Query().Get("id"))

    // Thread-safe cache lookup
    if cached, found := responseCache.Get(cacheKey); found {
        response := cached.(APIResponse)
        response.Cached = true

        w.Header().Set("Content-Type", "application/json")
        json.NewEncoder(w).Encode(response)
        return
    }

    // Simulate expensive operation
    time.Sleep(2 * time.Second)

    response := APIResponse{
        Data: map[string]interface{}{
            "result": "expensive computation result",
            "value":  42,
        },
        Timestamp: time.Now(),
        Cached:    false,
    }

    // Thread-safe cache storage
    responseCache.Set(cacheKey, response)

    w.Header().Set("Content-Type", "application/json")
    json.NewEncoder(w).Encode(response)
}

func main() {
    http.HandleFunc("/api/data", expensiveAPIHandler)

    fmt.Println("Server starting on :8080")
    fmt.Println("Try: http://localhost:8080/api/data?id=123")

