func (h *userRequestHandler) HandleUserRequest(req UserRequest) Response {
    validation := h.validator.ValidateUserRequest(req)
    if !validation.IsValid {
        return Response{
            Success: false,
            Error:   formatValidationErrors(validation.Errors),
        }
    }

    normalizedData := h.normalizer.NormalizeUserData(req)

    user, err := h.userManager.CreateOrUpdateUser(normalizedData)
    if err != nil {
        return Response{
            Success: false,
            Error:   err.Error(),
        }
    }

    if err := h.notifier.SendUserNotifications(user); err != nil {
        return Response{
            Success: false,
            Error:   err.Error(),
        }
    }

    return Response{
        Success: true,
        Data:    user,
    }
}

func formatValidationErrors(errors []ValidationError) string {
    var messages []string
    for _, err := range errors {
        messages = append(messages, fmt.Sprintf("%s: %s", err.Field, err.Message))
    }
    return strings.Join(messages, ", ")
