```typescript
class RequestValidator implements IRequestValidator {
  validate(request: UserRequest): ValidationResult {
    const errors: string[] = [];

    // Validate Name
    if (!request.Name || typeof request.Name !== 'string') {
      errors.push('Name is required and must be a string');
    } else if (request.Name.trim().length === 0) {
      errors.push('Name cannot be empty');
    } else if (request.Name.length > 100) {
      errors.push('Name must be less than 100 characters');
    }

    // Validate Email
    if (!request.Email || typeof request.Email !== 'string') {
      errors.push('Email is required and must be a string');
    } else if (!this.isValidEmail(request.Email)) {
      errors.push('Email format is invalid');
    }

    // Validate Age (optional)
    if (request.Age !== undefined) {
      if (typeof request.Age !== 'number' || request.Age < 0 || request.Age > 150) {
        errors.push('Age must be a valid number between 0 and 150');
      }
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  private isValidEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  }
}
