class DataNormalizer implements IDataNormalizer {
  normalize(request: UserRequest): NormalizedUserData {
    if (!request.Name || !request.Email) {
      throw new Error('Invalid request: Name and Email are required for normalization');
    }

    const normalized: NormalizedUserData = {
      name: this.normalizeName(request.Name),
      email: this.normalizeEmail(request.Email)
    };

    if (request.Age !== undefined) {
      normalized.age = request.Age;
    }

    return normalized;
  }

  private normalizeName(name: string): string {
    return name.trim().replace(/\s+/g, ' ');
  }

  private normalizeEmail(email: string): string {
    return email.trim().toLowerCase();
  }
}
