## 3. User Repository Implementation

```typescript
class UserRepository implements IUserRepository {
  private users: Map<string, User> = new Map();
  private emailIndex: Map<string, string> = new Map();

  async findByEmail(email: string): Promise<User | null> {
    const normalizedEmail = email.toLowerCase();
    const userId = this.emailIndex.get(normalizedEmail);

    if (!userId) {
      return null;
    }

    return this.users.get(userId) || null;
  }

  async create(userData: NormalizedUserData): Promise<User> {
    const user: User = {
      id: this.generateUserId(),
      name: userData.name,
      email: userData.email,
      age: userData.age
    };

    this.users.set(user.id, user);
    this.emailIndex.set(user.email, user.id);

    return user;
  }

  async update(user: User, updates: Partial<NormalizedUserData>): Promise<User> {
    const existingUser = this.users.get(user.id);
    if (!existingUser) {
      throw new Error('User not found');
    }

    const updatedUser: User = {
      ...existingUser,
      ...updates
    };

    this.users.set(user.id, updatedUser);

    // Update email index if email changed
    if (updates.email && updates.email !== existingUser.email) {
      this.emailIndex.delete(existingUser.email);
      this.emailIndex.set(updates.email, user.id);
    }

    return updatedUser;
  }

  private generateUserId(): string {
    return `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}
