class ResponseBuilder implements IResponseBuilder {
  buildSuccess(user: User): SuccessResponse {
    if (!user || !user.id) {
      throw new Error('Valid user with ID is required to build success response');
    }

    return {
      UserID: user.id
    };
  }

  buildError(errors: string[]): ErrorResponse {
    if (!errors || errors.length === 0) {
      return {
        Error: 'An unknown error occurred'
      };
    }

    // Validate error messages
    const validErrors = errors.filter(error => 
      error && typeof error === 'string' && error.trim().length > 0
    );

    if (validErrors.length === 0) {
      return {
        Error: 'Invalid error information provided'
      };
    }

    return {
      Error: validErrors.length === 1 ? validErrors[0] : validErrors.join('; ')
    };
  }
}
