# Refactored handleRequest Implementation

## Pipeline Composition

```typescript
async function handleRequest(
  request: UserRequest,
  validator: IRequestValidator,
  normalizer: IDataNormalizer,
  repository: IUserRepository,
  notificationService: INotificationService,
  responseBuilder: IResponseBuilder
): Promise<SuccessResponse | ErrorResponse> {

  // Step 1: Validate request
  const validationResult = validator.validate(request);
  if (!validationResult.isValid) {
    return responseBuilder.buildError(validationResult.errors);
  }

  try {
    // Step 2: Normalize data
    const normalizedData = normalizer.normalize(request);

    // Step 3: Check if user exists
    const existingUser = await repository.findByEmail(normalizedData.email);

    let user: User;
    if (existingUser) {
      // Step 4a: Update existing user
      user = await repository.update(existingUser, normalizedData);
    } else {
      // Step 4b: Create new user
      user = await repository.create(normalizedData);

      // Step 5: Send welcome notification for new users
      await notificationService.sendWelcomeEmail(user);
    }

    // Step 6: Track user event
    const eventName = existingUser ? 'user_updated' : 'user_created';
    await notificationService.trackUserEvent(user, eventName);

    // Step 7: Build success response
    return responseBuilder.buildSuccess(user);

  } catch (error) {
    // Handle any processing errors
    const errorMessage = error instanceof Error ? error.message : 'Processing failed';
    return responseBuilder.buildError([errorMessage]);
  }
}
```

