```go
package main

import (
    "fmt"
    "io"
    "mime/multipart"
    "net/http"
    "os"
    "path/filepath"
    "regexp"
    "strings"
)

// Secure filename sanitization
func sanitizeFilename(filename string) (string, error) {
    // Remove path separators and dangerous characters
    cleaned := filepath.Base(filename)
    cleaned = strings.ReplaceAll(cleaned, "..", "")
    cleaned = strings.ReplaceAll(cleaned, "/", "")
    cleaned = strings.ReplaceAll(cleaned, "\\", "")

    // Validate filename pattern
    validName := regexp.MustCompile(`^[a-zA-Z0-9._-]+$`)
    if !validName.MatchString(cleaned) {
        return "", fmt.Errorf("invalid filename characters")
    }

    // Prevent empty or hidden files
    if len(cleaned) == 0 || strings.HasPrefix(cleaned, ".") {
        return "", fmt.Errorf("invalid filename format")
    }

    return cleaned, nil
}

// Secure file upload handler
func uploadHandler(w http.ResponseWriter, r *http.Request) {
    // Limit request size (32MB)
    r.Body = http.MaxBytesReader(w, r.Body, 32<<20)

    if err := r.ParseMultipartForm(10 << 20); err != nil {
        http.Error(w, "File too large", http.StatusBadRequest)
        return
    }

    file, header, err := r.FormFile("upload")
    if err != nil {
        http.Error(w, "Invalid file upload", http.StatusBadRequest)
        return
    }
    defer file.Close()

    // CRITICAL FIX: Sanitize filename to prevent path traversal
    safeFilename, err := sanitizeFilename(header.Filename)
    if err != nil {
        http.Error(w, "Invalid filename", http.StatusBadRequest)
        return
    }

    // Validate file type by content
    buffer := make([]byte, 512)
    _, err = file.Read(buffer)
    if err != nil {
        http.Error(w, "Cannot read file", http.StatusInternalServerError)
        return
    }
    file.Seek(0, 0) // Reset file pointer

    contentType := http.DetectContentType(buffer)
    allowedTypes := map[string]bool{
        "image/jpeg": true,
        "image/png":  true,
        "text/plain": true,
    }

    if !allowedTypes[contentType] {
        http.Error(w, "File type not allowed", http.StatusBadRequest)
        return
    }

    // Create secure upload path
    uploadDir := "/uploads"
    safePath := filepath.Join(uploadDir, safeFilename)

    // Verify path is within upload directory
    if !strings.HasPrefix(safePath, uploadDir+string(os.PathSeparator)) {
        http.Error(w, "Invalid file path", http.StatusBadRequest)
        return
    }

    dst, err := os.Create(safePath)
    if err != nil {
        http.Error(w, "Cannot create file", http.StatusInternalServerError)
        return
    }
    defer dst.Close()

    // Copy with size limit
    _, err = io.CopyN(dst, file, 10<<20) // 10MB limit
    if err != nil && err != io.EOF {
        http.Error(w, "Upload failed", http.StatusInternalServerError)
        return
    }

    fmt.Fprintf(w, "File uploaded successfully")
}
