// File validation middleware
func validateUploadSecurity(uploadPath string) error {
    // Ensure upload directory exists and has proper permissions
    info, err := os.Stat("/uploads")
    if err != nil {
        return fmt.Errorf("upload directory not accessible")
    }

    if !info.IsDir() {
        return fmt.Errorf("upload path is not a directory")
    }

    // Check if path escapes upload directory
    absPath, err := filepath.Abs(uploadPath)
    if err != nil {
        return fmt.Errorf("cannot resolve absolute path")
    }

    absUpload, err := filepath.Abs("/uploads")
    if err != nil {
        return fmt.Errorf("cannot resolve upload directory")
    }

    if !strings.HasPrefix(absPath, absUpload) {
        return fmt.Errorf("path traversal attempt detected")
    }

    return nil
}
