// Helper function to check if array is sorted in ascending order
func isSorted(arr []int) bool {
	// Edge case: empty array is considered sorted
	if len(arr) == 0 {
		return true
	}

	for i := 1; i < len(arr); i++ {
		if arr[i-1] > arr[i] {
			return false
		}
	}
	return true
}

// Helper function to check if two arrays contain the same elements (same frequency)
func hasSameElements(arr1, arr2 []int) bool {
	// Edge case: both empty arrays have same elements
	if len(arr1) == 0 && len(arr2) == 0 {
		return true
	}

	if len(arr1) != len(arr2) {
		return false
	}

	// Count frequency of elements in both arrays
	freq1 := make(map[int]int)
	freq2 := make(map[int]int)

	for _, v := range arr1 {
		freq1[v]++
	}

	for _, v := range arr2 {
		freq2[v]++
	}

	// Compare frequency maps
	return reflect.DeepEqual(freq1, freq2)
}
